glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec3 col = c.rgb;
  vec2 p = uv * vec2(14.0 * uRatio, 14.0);
  p.y += uTime * 1.5;
  vec2 id = floor(p);
  vec2 f = fract(p) - 0.5;
  float a = uTime * 3.0 + hash(id) * 6.28;
  f = mat2(cos(a), -sin(a), sin(a), cos(a)) * (f - (vec2(hash(id + 1.0), hash(id + 2.0)) - 0.5) * 0.5);
  float r = step(abs(f.x), 0.14) * step(abs(f.y), 0.06) * step(0.6, hash(id + 5.0));
  vec3 cc = hueRotate(vec3(1.0, 0.2, 0.2), hash(id + 9.0) * 6.28);
  return vec4(mix(col, cc, r * uAmount), c.a);
}
